using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
using MC2Pack;
namespace Astera {
sealed class MinecraftSettingsForm:AsteraDialog {
 internal Preferences Result;
 internal readonly ComboBox LauncherChoice=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=610};
 internal readonly TextBox ProfilePath=new TextBox{Width=610},PrismData=new TextBox{Width=610},PrismExe=new TextBox{Width=610};
 readonly ComboBox instances=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=610};
 static void StyleSelector(ComboBox box){box.FlatStyle=FlatStyle.Flat;box.DrawMode=DrawMode.OwnerDrawFixed;box.ItemHeight=24;box.DrawItem+=delegate(object sender,DrawItemEventArgs e){e.Graphics.Clear(Color.FromArgb(28,36,57));string text=e.Index>=0?Convert.ToString(box.Items[e.Index]):box.Text;var bounds=e.Bounds;bounds.X+=6;bounds.Width-=12;TextRenderer.DrawText(e.Graphics,text,e.Font,bounds,Color.White,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);};}
 internal MinecraftSettingsForm(Preferences original,string key){Text="Minecraft settings";Size=new Size(760,730);MinimumSize=new Size(700,650);StartPosition=FormStartPosition.CenterParent;
  var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(20)};
  var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=60,Padding=new Padding(20,4,20,8),FlowDirection=FlowDirection.RightToLeft};Controls.Add(flow);Controls.Add(footer);
  Action<string> note=t=>flow.Controls.Add(new Label{Text=t,AutoSize=true,MaximumSize=new Size(650,0),Margin=new Padding(0,6,0,6)});
  Action<Control> style=c=>{c.BackColor=Color.FromArgb(28,36,57);c.ForeColor=Color.White;};
  Func<string,TextBox,bool,AsteraButton> row=(title,field,exe)=>{note(title);var panel=new FlowLayoutPanel{Width=670,Height=40,WrapContents=false};field.Width=530;style(field);var choose=new AsteraButton{Text="Choose…"};choose.Click+=delegate{if(exe){using(var picker=new OpenFileDialog{Filter="Prism Launcher|prismlauncher.exe",FileName=field.Text})if(picker.ShowDialog(this)==DialogResult.OK){field.Text=picker.FileName;string portable=Path.GetDirectoryName(field.Text);if(File.Exists(Path.Combine(portable,"prismlauncher.cfg")))PrismData.Text=portable;}}else using(var picker=new ExplorerFolderDialog{Description=title,SelectedPath=field.Text})if(picker.ShowDialog(this)==DialogResult.OK)field.Text=picker.SelectedPath;};panel.Controls.AddRange(new Control[]{field,choose});flow.Controls.Add(panel);return choose;};
  note("Launch Minecraft² using");LauncherChoice.Items.AddRange(new object[]{"CurseForge","Prism Launcher"});style(LauncherChoice);StyleSelector(LauncherChoice);flow.Controls.Add(LauncherChoice);
  ProfilePath.Text=original.Profile;row("Minecraft instance or game folder",ProfilePath,false);

  PrismData.Text=String.IsNullOrWhiteSpace(original.PrismDataRoot)?PrismProfiles.DefaultData:original.PrismDataRoot;
  PrismExe.Text=String.IsNullOrWhiteSpace(original.PrismExecutable)?PrismProfiles.DefaultExecutable():original.PrismExecutable;
  int start=flow.Controls.Count;row("Prism launcher data folder",PrismData,false);row("Prism application",PrismExe,true);note("Existing Prism instances");flow.Controls.Add(instances);style(instances);StyleSelector(instances);
  var actions=new FlowLayoutPanel{Width=660,Height=48,WrapContents=true};var refresh=new AsteraButton{Text="Find instances"};var create=new AsteraButton{Text="Create Minecraft² instance"};actions.Controls.AddRange(new Control[]{refresh,create});flow.Controls.Add(actions);
  var prismControls=flow.Controls.Cast<Control>().Skip(start).ToArray();
  var cfSetup=new AsteraButton{Text="Create CurseForge setup ZIP"};flow.Controls.Add(cfSetup);
  var cfNote=new Label{Text="No CurseForge instance yet? Create a setup ZIP, import it in CurseForge, then choose the new profile above. Astera supplies the pack after linking.",AutoSize=true,MaximumSize=new Size(650,0),Margin=new Padding(0,6,0,8)};flow.Controls.Add(cfNote);
  var detail=new Label{Text="Prism handles Minecraft downloads, Java and your sign-in. Astera installs and updates the pack inside the selected instance.",AutoSize=true,MaximumSize=new Size(650,0),Margin=new Padding(0,6,0,8)};flow.Controls.Add(detail);
  var packs=new CheckBox{Text="Set up supplied resource packs when updating",Checked=original.ConfigurePacks,AutoSize=true,Margin=new Padding(0,10,0,10)};flow.Controls.Add(packs);
  var advanced=new CheckBox{Text="Show advanced update channel",AutoSize=true};flow.Controls.Add(advanced);var channel=new TextBox{Text=original.FeedUrl,Width=650,Visible=false};style(channel);flow.Controls.Add(channel);advanced.CheckedChanged+=delegate{channel.Visible=advanced.Checked;};
  var save=new AsteraButton{Text="Save"};footer.Controls.Add(save);AcceptButton=save;
  Action discover=delegate{instances.Items.Clear();foreach(var item in PrismProfiles.Discover(PrismData.Text.Trim()))instances.Items.Add(item);instances.SelectedItem=instances.Items.Cast<PrismInstance>().FirstOrDefault(p=>p.GameRoot.Equals(ProfilePath.Text.Trim(),StringComparison.OrdinalIgnoreCase));if(instances.Items.Count==0)detail.Text="No instances found. Create Minecraft² here, or choose an existing Prism instance folder.";else detail.Text="Choose an instance to link. Its worlds and personal files stay in place.";};
  refresh.Click+=delegate{try{discover();}catch(Exception e){MessageBox.Show(this,e.Message,"Prism instances");}};
  instances.SelectionChangeCommitted+=delegate{var selected=instances.SelectedItem as PrismInstance;if(selected!=null)ProfilePath.Text=selected.GameRoot;};
  bool checking=false;create.Click+=async delegate{if(checking)return;checking=true;create.Enabled=save.Enabled=LauncherChoice.Enabled=false;detail.Text="Checking the signed Minecraft² release…";try{string address=channel.Text.Trim();new Transport().Address(address);var release=await Task.Run(()=>new UpdateClient(key).Check(address,CancellationToken.None));if(IsDisposed)return;var made=PrismProfiles.Create(PrismData.Text.Trim(),release.Release);ProfilePath.Text=made.GameRoot;discover();instances.SelectedItem=instances.Items.Cast<PrismInstance>().FirstOrDefault(p=>p.Root==made.Root);detail.Text="Instance created. Save to link it, then choose Update in Minecraft² to install the pack.";}catch(Exception e){if(!IsDisposed)MessageBox.Show(this,e.Message,"Create Prism instance");}finally{checking=false;if(!IsDisposed)create.Enabled=save.Enabled=LauncherChoice.Enabled=true;}};
  cfSetup.Click+=async delegate{if(checking)return;checking=true;cfSetup.Enabled=save.Enabled=LauncherChoice.Enabled=false;try{string address=channel.Text.Trim();var update=await Task.Run(()=>new UpdateClient(key).Check(address,CancellationToken.None));if(IsDisposed)return;using(var picker=new SaveFileDialog{Filter="CurseForge setup ZIP|*.zip",FileName="Minecraft2-Setup.zip",Title="Save Minecraft² CurseForge setup"}){if(picker.ShowDialog(this)!=DialogResult.OK)return;CurseForgeSetup.Create(update.Release,picker.FileName);cfNote.Text="Setup ZIP created. In CurseForge choose Import and select it; then use Choose above to link its new profile.";}}catch(Exception e){if(!IsDisposed)MessageBox.Show(this,e.Message,"CurseForge setup");}finally{checking=false;if(!IsDisposed)cfSetup.Enabled=save.Enabled=LauncherChoice.Enabled=true;}};
  LauncherChoice.SelectedIndexChanged+=delegate{bool prism=LauncherChoice.SelectedIndex==1;foreach(var control in prismControls)control.Visible=prism;detail.Visible=prism;cfSetup.Visible=cfNote.Visible=!prism;};
  bool initial=original.MinecraftLauncher=="prism";try{if(!String.IsNullOrWhiteSpace(original.Profile))initial=Profiles.Read(original.Profile).IsPrism;}catch(Exception){}
  LauncherChoice.SelectedIndex=initial?1:0;if(initial)try{discover();}catch(Exception e){detail.Text=e.Message;}
  save.Click+=delegate{try{if(checking)return;var copy=Engine.Json.Deserialize<Preferences>(Engine.Json.Serialize(original));bool prism=LauncherChoice.SelectedIndex==1;string path=ProfilePath.Text.Trim();if(!String.IsNullOrWhiteSpace(path)){var selected=Profiles.Read(path);if(selected.IsPrism!=prism)throw new IOException("Choose an instance for the selected launcher");path=selected.Path;}if(!String.IsNullOrWhiteSpace(channel.Text))new Transport().Address(channel.Text.Trim());if(prism){PrismProfiles.InstanceDirectory(PrismData.Text.Trim());if(!File.Exists(PrismExe.Text.Trim())||!Path.GetFileName(PrismExe.Text.Trim()).Equals("prismlauncher.exe",StringComparison.OrdinalIgnoreCase))throw new IOException("Choose Prism Launcher's application first");if(!String.IsNullOrWhiteSpace(path))PrismProfiles.Launch(PrismExe.Text.Trim(),PrismData.Text.Trim(),path);}copy.Profile=path;copy.FeedUrl=channel.Text.Trim();copy.ConfigurePacks=packs.Checked;copy.MinecraftLauncher=prism?"prism":"curseforge";copy.PrismDataRoot=PrismData.Text.Trim();copy.PrismExecutable=PrismExe.Text.Trim();Result=copy;DialogResult=DialogResult.OK;Close();}catch(Exception e){MessageBox.Show(this,e.Message,"Minecraft² settings");}};
 }
}
sealed partial class LibraryForm {
 async void ConfigureMinecraft(){var prior=store.Settings;using(var dialog=new MinecraftSettingsForm(prior,channel.PublicKeyXml)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;ClearPrepared();minecraftChannelBehind=false;feed=null;plan=null;updateReady=false;store.Settings=dialog.Result;GameProfile linked=null;try{linked=Profiles.Read(store.Settings.Profile);}catch(Exception){}RememberMinecraftLibrary(linked);store.Save();RefreshView();if(MinecraftSquaredSelected&&NeedsProfileCheck(prior,store.Settings))await CheckMinecraft(false);}}
 void OpenMinecraft(){try{if(String.IsNullOrWhiteSpace(store.Settings.Profile)){ConfigureMinecraft();return;}var profile=Profiles.Read(store.Settings.Profile);if(!profile.IsPrism){BeginMinecraftLaunch(profile,CurseForgeLaunchInfo(profile.Path));return;}string executable=String.IsNullOrWhiteSpace(store.Settings.PrismExecutable)?PrismProfiles.DefaultExecutable():store.Settings.PrismExecutable;string data=String.IsNullOrWhiteSpace(store.Settings.PrismDataRoot)?PrismProfiles.DefaultData:store.Settings.PrismDataRoot;System.Diagnostics.Process.Start(PrismProfiles.Launch(executable,data,profile.Path));TrackLaunchedGame("builtin:0",new CustomGame{Executable=profile.Path,Platform="minecraft"});}catch(Exception error){AsteraDiagnostics.Write("Minecraft launcher",error);MessageBox.Show(this,error.Message,"Play Minecraft²");}}
}
}
